contents.itemFilterFormula:
and(
    switchCase(item.skill_type, 'Active', true, 'Passive', true, 'Other', true, false),
    and(
        or(
            equalText(item.skill_type, skill_type_filter),
            equalText(skill_type_filter, "All")
        ),
        or(
            equalText(item.class, skill_class_filter),
            equalText(skill_class_filter, "")
        )
    )
)
